              // reading data into char array\n        {\n            buffer[count++] = SoftSerial.read();      // writing data into array\n            if(count == 64)break;\n        }\n        Serial.write(buffer, count);     // if no data transmission ends, write buffer to hardware serial port\n        clearBufferArray();             // call clearBufferArray function to clear the stored data from the array\n        count = 0;                      // set counter of while loop to zero\n    }\n    if (Serial.available())             // if data is available on hardware serial port ==> data is coming from PC or notebook\n    SoftSerial.write(Serial.read());    // write it to the SoftSerial shield\n}\nvoid clearBufferArray()                 // function to clear buffer array\n{\n    // clear all index of array with command NULL\n    for (int i=0; i<count; i++)\n    {\n        buffer[i]=NULL;\n    }                  \n}\n"})}),"\n",(0,s.jsxs)(i.ul,{children:["\n",(0,s.jsxs)(i.li,{children:[(0,s.jsx)(i.strong,{children:"\u6B65\u9AA4 2."})," \u6253\u5F00\u4E32\u53E3\u76D1\u89C6\u5668\uFF0C\u5361\u7247\u4FE1\u606F\u53EF\u4EE5\u663E\u793A\u5982\u4E0B\uFF1A"]}),"\n"]}),"\n",(0,s.jsx)(i.p,{children:(0,s.jsx)(i.img,{src:"https://files.seeedstudio.com/wiki/Grove-125KHz_RFID_Reader/img/Read_Data_.jpg",alt:""})}),"\n",(0,s.jsx)(i.h2,{id:"wiegand-\u6A21\u5F0F",children:"Wiegand \u6A21\u5F0F"}),"\n",(0,s.jsxs)(i.p,{children:['\uFF08\u8DF3\u7EBF\u8BBE\u7F6E\u5230\u53F3\u8FB9\u4E24\u4E2A\u5F15\u811A\uFF09\n\u60A8\u9700\u8981\u5C06\u8DF3\u7EBF\u9009\u62E9\u5230"W"\u6765\u8FDB\u5165\u6B64\u6A21\u5F0F\u3002\n\u9002\u7528\u4E8E Seeeduino \u7684 ',(0,s.jsx)(i.a,{href:"https://files.seeedstudio.com/wiki/Grove-125KHz_RFID_Reader/res/RFID_Wiegand_INT.zip",children:"Wiegand \u6F14\u793A\u4EE3\u7801"})," \u8BBE\u8BA1\u7528\u4E8E\u5728\u4E2D\u65AD\u6A21\u5F0F\u4E0B\u8BFB\u53D6 Wiegand \u6570\u636E\u3002"]}),"\n",(0,s.jsx)(i.p,{children:"\u5728 Wiegand \u6A21\u5F0F\u4E0B\uFF0C\u8F93\u51FA\u6570\u6